/// A C wide literal (`L"..."`) as Rust: the UTF-16 of a `str`, NUL-terminated, built at
/// compile time. `data_port::wstr_units::<N>` is the same zero-padded into a `WCHAR s[N]`.
macro_rules! wstr {
    ($s:expr) => {{
        const S: &str = $s;
        const N: usize = data_port::wstr_len(S);
        const W: [u16; N] = data_port::wstr_units::<N>(S);
        &W
    }};
}

mod data_port {
    pub(super) const fn wstr_len(s: &str) -> usize {
        let b = s.as_bytes();
        let (mut i, mut n) = (0, 1);
        while i < b.len() {
            let c = b[i];
            let w = if c < 0x80 { 1 } else if c < 0xE0 { 2 } else if c < 0xF0 { 3 } else { 4 };
            n += if w == 4 { 2 } else { 1 };
            i += w;
        }
        n
    }

    pub(super) const fn wstr_units<const N: usize>(s: &str) -> [u16; N] {
        let b = s.as_bytes();
        let mut out = [0u16; N];
        let (mut i, mut o) = (0, 0);
        while i < b.len() {
            let c = b[i] as u32;
            let (cp, w) = if c < 0x80 {
                (c, 1)
            } else if c < 0xE0 {
                (((c & 0x1F) << 6) | (b[i + 1] as u32 & 0x3F), 2)
            } else if c < 0xF0 {
                (((c & 0x0F) << 12) | ((b[i + 1] as u32 & 0x3F) << 6) | (b[i + 2] as u32 & 0x3F), 3)
            } else {
                let v = ((c & 0x07) << 18)
                    | ((b[i + 1] as u32 & 0x3F) << 12)
                    | ((b[i + 2] as u32 & 0x3F) << 6)
                    | (b[i + 3] as u32 & 0x3F);
                (v, 4)
            };
            if cp >= 0x10000 {
                out[o] = (0xD800 | ((cp - 0x10000) >> 10)) as u16;
                out[o + 1] = (0xDC00 | ((cp - 0x10000) & 0x3FF)) as u16;
                o += 2;
            } else {
                out[o] = cp as u16;
                o += 1;
            }
            i += w;
        }
        out
    }
}

/// `MODIFIERS` with its flexible `ModNumber` initialized in place: 8 element(s).
#[repr(C)]
pub struct MODIFIERS_x8 {
    pub pVkToBit: PVK_TO_BIT,
    pub wMaxModBits: WORD,
    pub ModNumber: [BYTE; 8],
}
const _: () = {
    assert!(core::mem::offset_of!(MODIFIERS_x8, pVkToBit) == core::mem::offset_of!(MODIFIERS, pVkToBit));
    assert!(core::mem::offset_of!(MODIFIERS_x8, wMaxModBits) == core::mem::offset_of!(MODIFIERS, wMaxModBits));
    assert!(core::mem::offset_of!(MODIFIERS_x8, ModNumber) == core::mem::offset_of!(MODIFIERS, ModNumber));
    assert!(core::mem::align_of::<MODIFIERS_x8>() == core::mem::align_of::<MODIFIERS>());
};

